+    fromPublicKey: SELF,
+    toPublicKey: 'channel-1',
+    text: 'anyone out there?',
+    timestamp: T0,
+    heardBy: [{ hash: '7f', name: 'Hilltop', snr: 4 }],
+    ...overrides,
+  };
