+/* MeshWars forwarder settings. CSS module per the containment rule in
+   CLAUDE.md; the section header and form rows reuse the shared settings
+   classes so it matches the sections around it. Theme tokens only. */
+
+.header {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+  margin-bottom: 1.5rem;
+  padding: 1rem 1.25rem;
+  background: var(--color-surface-hover);
+  border: 1px solid var(--color-surface-active);
+  border-radius: var(--radius-md);
+}
+
+.title {
+  margin: 0;
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+}
+
+.enableBox {
+  width: auto;
+  margin: 0;
+  cursor: pointer;
+}
+
+
+
+.dimmed {
+  opacity: 0.5;
+  transition: opacity 0.2s;
+}
+
+.description {
+  margin: 0 0 1rem 1.75rem;
+  color: var(--color-text-muted);
+  line-height: 1.5;
+}
+
+
+.help {
+  font-size: 12px;
+  color: var(--color-text-subtle);
+  margin: 0.35rem 0 0 0;
+}
+
+.checkLabel {
+  display: flex;
+  align-items: center;
+  gap: 0.5rem;
+  cursor: pointer;
+}
+
+.checkLabel input {
+  width: auto;
+  margin: 0;
+}
+
