+    expect(layoutCss).toMatch(/\.wrapRow\s*\{[^}]*flex-wrap:\s*wrap/);
+    // A max-width-only query would miss phones in landscape (#5051-#5054).
+    expect(layoutCss).not.toMatch(/@media/);
