+}
+
+.handle {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  min-width: 2rem;
+  min-height: 2rem;
+  cursor: grab;
+  color: var(--color-text-subtle);
+  border-radius: var(--radius-md);
+}
+
+.dragging .handle {
+  cursor: grabbing;
+  color: var(--color-accent);
+}
+
+.handle:focus-visible {
+  outline: 2px solid var(--color-accent);
