+
+function ruleBody(css: string, selector: string): string | null {
+  const escaped = selector.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
+  const m = css.match(new RegExp(escaped + '\\s*\\{([^}]*)\\}'));
+  return m ? m[1] : null;
+}
+
