+
+      migration.up(db);
+
+      const row = db.prepare(`SELECT value, unit FROM telemetry WHERE telemetryType = 'envCurrent'`).get() as {
+        value: number;
+        unit: string;
+      };
+      expect(row.unit).toBe('mA');
+      expect(row.value).toBeCloseTo(0.12, 5);
+      db.close();
+    });
