+    const cov = coveragePct();
+    const readyButUnlisted = Object.entries(cov)
+      .filter(([code, pct]) => pct >= READY_THRESHOLD_PCT && !listed.has(code))
+      .map(([code, pct]) => `${code} (${pct.toFixed(1)}%)`);
