+    await expect(repo.replaceAnchors([1], [bad])).rejects.toThrow();
+
+    const surviving = await repo.getAnchorsByNodeNum(1);
+    expect(surviving.map((a) => a.anchorNodeNum).sort()).toEqual([10, 11]);
+  });
