+    expect(res.status).toBe(403);
+  });
+
+  it('400s when sourceId is missing from the body', async () => {
+    const agent = await harness.loginAs(harness.admin);
+    const res = await agent.put('/auto-favorite-targets/12345').send({ enabled: true });
