+      .send({ isIgnored: true });
+
+    expect(res.status).toBe(403);
+    expect(res.body.code).toBe('FORBIDDEN');
+  });
+
+  it('honors an admin token (bypasses the permission check)', async () => {
+    const token = await harness.tokenFor(harness.admin);
