+    // v2.7.26 wire form (proto3 varints, ascending tags):
+    //   tag 1 (enabled)               -> 0x08 0x01
+    //   tag 2 (position_dedup_enabled)-> 0x10 0x01
+    //   tag 3 (position_precision_bits)-> 0x18 0x0d
