+    // add_contact is skipped on mismatch (stored key is stale), so the DM can still fail.
+    expect(isDeviceDbWarningMitigatable({ user: { id: '!1', publicKey: 'AQID' }, keyMismatchDetected: true })).toBe(false);
+  });
