+    // "humidity" => "Relative Humidity" sorts between Battery Level and Voltage
+    const after = sortTypes(['batteryLevel', 'voltage', 'humidity'], favorites);
+    expect(after).toEqual(['batteryLevel', 'humidity', 'voltage']);
