+    expect(unit).toBe('mA');
+  });
+
+  it('converts 0.012 W to 12 mW', () => {
+    const { value, unit } = scaleMeasurement(0.012, 'W');
+    expect(value).toBeCloseTo(12, 6);
+    expect(unit).toBe('mW');
+  });
+
+  it('converts 1500 mA to 1.5 A', () => {
+    const { value, unit } = scaleMeasurement(1500, 'mA');
+    expect(value).toBeCloseTo(1.5, 6);
+    expect(unit).toBe('A');
+  });
+
