+
+          {/* Public Key */}
+          <div className="node-detail-card node-detail-card-2col">
+            <div className="node-detail-label">{t('meshcore.public_key', 'Public Key')}</div>
+            <div className="node-detail-value node-detail-public-key" title={publicKey}>
+              {publicKey}
+            </div>
+          </div>
+        </div>
+      )}
+    </div>
+  );
+};
