+  }) as any;
+  res.json = vi.fn((body: any) => {
+    res.body = body;
+    return res as Response;
+  }) as any;
+  return res as Response & { statusCode?: number; body?: any };
+}
+
+function makeReq(overrides: Record<string, any> = {}): Request {
+  return {
+    method: 'POST',
+    path: '/some-mutation',
+    headers: {},
+    body: {},
+    session: {},
+    ...overrides,
+  } as unknown as Request;
+}
