+        routingErrorReceived INTEGER,
+        deliveryState TEXT,
+        wantAck INTEGER,
+        ackFromNode INTEGER,
+        createdAt INTEGER NOT NULL,
+        decrypted_by TEXT,
+        sourceId TEXT
+      )
