+  const insert = (id: string, portnum: number | null, rxTime: number, text = 'x') => {
+    const now = Date.now();
+    db.prepare(
+      `INSERT INTO messages (id, fromNodeNum, toNodeNum, fromNodeId, toNodeId, text, channel, portnum, timestamp, rxTime, createdAt)
+       VALUES (?, ?, ?, ?, ?, ?, -1, ?, ?, ?, ?)`
