+  { src: '/images/features/security.png', label: 'Security Scanner', accent: '#f97316' },
+]
+
+const active = ref(0)
+const direction = ref(1) // 1 = forward, -1 = backward
+let timer = null
+let isPaused = false
+
+function next() {
+  direction.value = 1
+  active.value = (active.value + 1) % slides.length
+}
+
+function goTo(idx) {
+  direction.value = idx > active.value ? 1 : -1
+  active.value = idx
+  resetTimer()
+}
+
+function resetTimer() {
+  clearInterval(timer)
+  timer = setInterval(() => {
+    if (!isPaused) next()
+  }, 5000)
+}
+
+function pause() { isPaused = true }
+function resume() { isPaused = false }
+
+onMounted(() => {
+  resetTimer()
+})
+
+onUnmounted(() => {
+  clearInterval(timer)
+})
+
+const accentColor = computed(() => slides[active.value].accent)
