+ * in mesh.proto
+ */
+export const RoutingError = {
+  NONE: 0,
+  NO_ROUTE: 1,
+  GOT_NAK: 2,
+  TIMEOUT: 3,
+  NO_INTERFACE: 4,
+  MAX_RETRANSMIT: 5,
