+      'user_permanently_deleted',
+      'users',
+      JSON.stringify({ userId, username: user.username }),
+      req.ip || null
+    );
+
+    return res.json({
+      success: true,
+      message: 'User permanently deleted'
+    });
+  } catch (error) {
+    logger.error('Error permanently deleting user:', error);
