+        status={connectedStatus}
+        loading={false}
+        onOpenSettings={vi.fn()}
+        actions={actions as any}
+        canControl
+      />,
+    );
+    for (const label of CONTROL_LABELS) {
+      expect(screen.getByText(label)).toBeInTheDocument();
+    }
+  });
+});
